initJs:
function(container, apiUrl, tables) {
  // 業務ロジックのインポート
  const {
    collectSalesData,
    classifySalesDataByProduct,
    classifySalesDataByStore,
    filterValidProductData,
    collectWeatherData,
    collectEventData,
    collectSeasonalData,
    analyzeCorrelationSalesWeather,
    analyzeCorrelationSalesEvent,
    analyzeCorrelationSalesSeason,
    compareWithHistoricalData,
    findAlternativeComparisonData,
    validateComparisonPeriod
  } = window.aiLogic || {};

  let currentProducts = [];
  let currentForecast = {};

  // エラー表示関数
  function showError(message) {
    window.aivicNotify.error(message);
    const errorDiv = container.querySelector('#error-message');
    if (errorDiv) {
      errorDiv.textContent = message;
      errorDiv.classList.remove('hidden');
      setTimeout(() => errorDiv.classList.add('hidden'), 5000);
    }
  }

  // 成功表示関数
  function showSuccess(message) {
    window.aivicNotify.success(message);
  }

  // バリデーション関数
  function validateInputs() {
    const storeId = container.querySelector('#select-store').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return false;
    }

    // 期間バリデーション（業務ロジック使用）
    if (validateComparisonPeriod) {
      const validation = validateComparisonPeriod(startDate, endDate);
      if (!validation.valid) {
        showError(validation.message);
        return false;
      }
    }

    return true;
  }

  // 数値バリデーション関数
  function validateNumber(value, fieldName, min = 0, max = null) {
    if (value === '' || value === null || value === undefined) return true;

    const num = parseFloat(value);
    if (isNaN(num)) {
      showError(`${fieldName}は数値を入力してください`);
      return false;
    }

    if (num < min) {
      showError(`${fieldName}は${min}以上の値を入力してください`);
      return false;
    }

    if (max !== null && num > max) {
      showError(`${fieldName}は${max}以下の値を入力してください`);
      return false;
    }

    return true;
  }

  // 店舗データ読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (!stores) return;

      const select = container.querySelector('#select-store');
      if (!select) return;

      select.innerHTML = '<option value="">店舗を選択してください</option>';

      stores.filter(store => store.有効フラグ).forEach(store => {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        select.appendChild(option);
      });
    } catch (error) {
      showError('店舗データの読み込みに失敗しました');
    }
  }

  // 商品検索・絞り込み
  async function searchProducts() {
    try {
      const keyword = container.querySelector('#input-search')?.value.trim() || '';
      const categoryId = container.querySelector('#select-category')?.value || '';

      const products = await window.aivicApi.list(2); // 商品マスタ
      if (!products) return;

      let filteredProducts = products.filter(product => product.有効フラグ);

      if (keyword) {
        filteredProducts = filteredProducts.filter(product => 
          product.商品名.includes(keyword) || 
          product.商品コード.includes(keyword)
        );
      }

      if (categoryId) {
        filteredProducts = filteredProducts.filter(product => 
          product.カテゴリID === categoryId
        );
      }

      currentProducts = filteredProducts;
      displayProducts(filteredProducts);
    } catch (error) {
      showError('商品検索に失敗しました');
    }
  }

  // 商品一覧表示
  function displayProducts(products) {
    const tbody = container.querySelector('#products-table tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    products.forEach(product => {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td>
          <input type="checkbox" class="product-checkbox" value="${product.商品ID}">
        </td>
        <td>${product.商品コード}</td>
        <td>${product.商品名}</td>
        <td>${product.カテゴリ名 || ''}</td>
        <td>¥${product.単価?.toLocaleString() || 0}</td>
        <td>${product.在庫数量 || 0}</td>
      `;
      tbody.appendChild(row);
    });
  }

  // 需要予測実行
  async function executeForecast() {
    if (!validateInputs()) return;

    try {
      const storeId = container.querySelector('#select-store').value;
      const startDate = container.querySelector('#input-start-date').value;
      const endDate = container.querySelector('#input-end-date').value;

      // 選択された商品を取得
      const selectedProductIds = Array.from(container.querySelectorAll('.product-checkbox:checked'))
        .map(cb => cb.value);

      if (selectedProductIds.length === 0) {
        showError('商品を選択してください');
        return;
      }

      // 売上データ収集（業務ロジック使用）
      const salesData = await collectSalesData(storeId, startDate, endDate);
      if (!salesData || salesData.length === 0) {
        showError('売上データが見つかりません');
        return;
      }

      // 商品別売上データ分類
      const productSalesData = classifySalesDataByProduct(salesData, selectedProductIds);

      // 有効な商品データのフィルタリング
      const validProductData = filterValidProductData(productSalesData);

      // 外部データ収集
      const weatherData = await collectWeatherData(storeId, startDate, endDate);
      const eventData = await collectEventData(storeId, startDate, endDate);
      const seasonalData = collectSeasonalData(startDate, endDate);

      // 相関分析
      const weatherCorrelation = analyzeCorrelationSalesWeather(validProductData, weatherData);
      const eventCorrelation = analyzeCorrelationSalesEvent(validProductData, eventData);
      const seasonalCorrelation = analyzeCorrelationSalesSeason(validProductData, seasonalData);

      // 過去データとの比較
      const historicalComparison = await compareWithHistoricalData(validProductData, storeId);

      // 予測結果の計算と表示
      const forecastResults = calculateForecastResults(
        validProductData,
        weatherCorrelation,
        eventCorrelation,
        seasonalCorrelation,
        historicalComparison
      );

      currentForecast = forecastResults;
      displayForecastResults(forecastResults);
      showSuccess('需要予測が完了しました');

    } catch (error) {
      console.error('Forecast error:', error);
      showError('需要予測の実行に失敗しました');
    }
  }

  // 予測結果計算
  function calculateForecastResults(productData, weatherCorr, eventCorr, seasonalCorr, historical) {
    const results = {};

    Object.keys(productData).forEach(productId => {
      const baseData = productData[productId];
      const avgSales = baseData.reduce((sum, item) => sum + item.販売数量, 0) / baseData.length;

      // 各要因の影響を加味した予測値計算
      let forecastValue = avgSales;

      if (weatherCorr[productId]) {
        forecastValue *= (1 + weatherCorr[productId].impact);
      }

      if (eventCorr[productId]) {
        forecastValue *= (1 + eventCorr[productId].impact);
      }

      if (seasonalCorr[productId]) {
        forecastValue *= (1 + seasonalCorr[productId].impact);
      }

      if (historical[productId]) {
        forecastValue = (forecastValue + historical[productId].avgSales) / 2;
      }

      results[productId] = {
        予測販売数量: Math.round(forecastValue),
        信頼度: calculateConfidence(weatherCorr[productId], eventCorr[productId], seasonalCorr[productId]),
        推奨発注量: Math.round(forecastValue * 1.1), // 安全在庫考慮
        根拠: generateForecastReason(weatherCorr[productId], eventCorr[productId], seasonalCorr[productId])
      };
    });

    return results;
  }

  // 信頼度計算
  function calculateConfidence(weather, event, seasonal) {
    let confidence = 0.5; // ベース信頼度

    if (weather && weather.correlation > 0.7) confidence += 0.2;
    if (event && event.correlation > 0.7) confidence += 0.2;
    if (seasonal && seasonal.correlation > 0.7) confidence += 0.1;

    return Math.min(confidence, 1.0);
  }

  // 予測根拠生成
  function generateForecastReason(weather, event, seasonal) {
    const reasons = [];

    if (weather && weather.impact > 0.1) {
      reasons.push('天候要因による増加');
    } else if (weather && weather.impact < -0.1) {
      reasons.push('天候要因による減少');
    }

    if (event && event.impact > 0.1) {
      reasons.push('イベント要因による増加');
    }

    if (seasonal && seasonal.impact > 0.1) {
      reasons.push('季節要因による増加');
    } else if (seasonal && seasonal.impact < -0.1) {
      reasons.push('季節要因による減少');
    }

    return reasons.length > 0 ? reasons.join('、') : '過去実績ベース';
  }

  // 予測結果表示
  function displayForecastResults(results) {
    const tbody = container.querySelector('#forecast-results tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    Object.keys(results).forEach(productId => {
      const product = currentProducts.find(p => p.商品ID === productId);
      const result = results[productId];

      if (!product) return;

      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${product.商品コード}</td>
        <td>${product.商品名}</td>
        <td>${result.予測販売数量}</td>
        <td>${Math.round(result.信頼度 * 100)}%</td>
        <td>
          <input type="number" class="order-quantity" 
                 data-product-id="${productId}" 
                 value="${result.推奨発注量}" 
                 min="0">
        </td>
        <td>${result.根拠}</td>
        <td>
          <button class="btn-adjust" data-product-id="${productId}">調整</button>
        </td>
      `;
      tbody.appendChild(row);
    });

    // 調整ボタンのイベントリスナー追加
    container.querySelectorAll('.btn-adjust').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const productId = e.target.dataset.productId;
        adjustOrderQuantity(productId);
      });
    });
  }

  // 発注量調整
  function adjustOrderQuantity(productId) {
    const input = container.querySelector(`input[data-product-id="${productId}"]`);
    if (!input) return;

    const currentValue = parseInt(input.value) || 0;
    const newValue = prompt('発注量を入力してください:', currentValue);

    if (newValue !== null && !isNaN(newValue) && newValue >= 0) {
      input.value = newValue;
      showSuccess('発注量を調整しました');
    }
  }

  // 発注データ保存
  async function saveOrderData() {
    try {
      const storeId = container.querySelector('#select-store').value;
      const orderDate = new Date().toISOString().split('T')[0];

      const orderQuantities = {};
      container.querySelectorAll('.order-quantity').forEach(input => {
        const productId = input.dataset.productId;
        const quantity = parseInt(input.value) || 0;
        if (quantity > 0) {
          orderQuantities[productId] = quantity;
        }
      });

      if (Object.keys(orderQuantities).length === 0) {
        showError('発注する商品がありません');
        return;
      }

      // 発注データ保存
      const orderData = {
        店舗ID: storeId,
        発注日: orderDate,
        発注明細: Object.keys(orderQuantities).map(productId => ({
          商品ID: productId,
          発注数量: orderQuantities[productId],
          予測根拠: currentForecast[productId]?.根拠 || ''
        })),
        作成日時: new Date().toISOString(),
        ステータス: '未承認'
      };

      await window.aivicApi.save(5, orderData); // 発注データテーブル
      showSuccess('発注データを保存しました');

      // 結果をクリア
      clearResults();

    } catch (error) {
      console.error('Save error:', error);
      showError('発注データの保存に失敗しました');
    }
  }

  // 結果クリア
  function clearResults() {
    const forecastTbody = container.querySelector('#forecast-results tbody');
    if (forecastTbody) {
      forecastTbody.innerHTML = '';
    }

    const productsTbody = container.querySelector('#products-table tbody');
    if (productsTbody) {
      productsTbody.innerHTML = '';
    }

    currentProducts = [];
    currentForecast = {};
  }

  // カテゴリデータ読み込み
  async function loadCategories() {
    try {
      const categories = await window.aivicApi.list(3); // カテゴリマスタ
      if (!categories) return;

      const select = container.querySelector('#select-category');
      if (!select) return;

      select.innerHTML = '<option value="">全カテゴリ</option>';

      categories.forEach(category => {
        const option = document.createElement('option');
        option.value = category.カテゴリID;
        option.textContent = category.カテゴリ名;
        select.appendChild(option);
      });
    } catch (error) {
      showError('カテゴリデータの読み込みに失敗しました');
    }
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // 検索ボタン
    const searchBtn = container.querySelector('#btn-search');
    if (searchBtn) {
      searchBtn.addEventListener('click', searchProducts);
    }

    // 予測実行ボタン
    const forecastBtn = container.querySelector('#btn-forecast');
    if (forecastBtn) {
      forecastBtn.addEventListener('click', executeForecast);
    }

    // 保存ボタン
    const saveBtn = container.querySelector('#btn-save');
    if (saveBtn) {
      saveBtn.addEventListener('click', saveOrderData);
    }

    // クリアボタン
    const clearBtn = container.querySelector('#btn-clear');
    if (clearBtn) {
      clearBtn.addEventListener('click', clearResults);
    }

    // 全選択チェックボックス
    const selectAllBtn = container.querySelector('#btn-select-all');
    if (selectAllBtn) {
      selectAllBtn.addEventListener('click', () => {
        const checkboxes = container.querySelectorAll('.product-checkbox');
        checkboxes.forEach(cb => cb.checked = true);
      });
    }

    // 全解除ボタン
    const deselectAllBtn = container.querySelector('#btn-deselect-all');
    if (deselectAllBtn) {
      deselectAllBtn.addEventListener('click', () => {
        const checkboxes = container.querySelectorAll('.product-checkbox');
        checkboxes.forEach(cb => cb.checked = false);
      });
    }

    // 検索フィールドでのEnterキー
    const searchInput = container.querySelector('#input-search');
    if (searchInput) {
      searchInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') {
          searchProducts();
        }
      });
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadStores();
      await loadCategories();
      setupEventListeners();

      // デフォルト日付設定
      const today = new Date();
      const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);

      const startDateInput = container.querySelector('#input-start-date');
      const endDateInput = container.querySelector('#input-end-date');

      if (startDateInput) {
        startDateInput.value = today.toISOString().split('T')[0];
      }

      if (endDateInput) {
        endDateInput.value = nextWeek.toISOString().split('T')[0];
      }

    } catch (error) {
      console.error('Initialization error:', error);
      showError('画面の初期化に失敗しました');
    }
  }

  // 初期化実行
  initialize();
}
